import React from 'react';
import type { TextareaHTMLAttributes } from 'react';
import styles from './TextArea.module.css';

export interface TextAreaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  label?: string;
  error?: string;
  fullWidth?: boolean;
}

export const TextArea: React.FC<TextAreaProps> = ({
  label,
  error,
  fullWidth = false,
  className = '',
  id,
  ...props
}) => {
  const generatedId = id || Math.random().toString(36).substring(7);

  const containerClasses = [
    styles.container,
    fullWidth ? styles.fullWidth : '',
    className
  ].filter(Boolean).join(' ');

  const textareaClasses = [
    styles.textarea,
    error ? styles.errorTextarea : '',
  ].filter(Boolean).join(' ');

  return (
    <div className={containerClasses}>
      {label && <label htmlFor={generatedId} className={styles.label}>{label}</label>}
      <textarea
        id={generatedId}
        className={textareaClasses}
        rows={props.rows || 4}
        {...props}
      />
      {error && <span className={styles.errorText}>{error}</span>}
    </div>
  );
};

import type { ConditionalBlueprint } from './Conditional';

export interface VisitedPageParams {
  not: boolean;
  pageId: string | null;
}

export const visitedPageBlueprint: ConditionalBlueprint<VisitedPageParams> = {
  id: 'visited_page',
  name: 'Visited page',
  template: 'The player has {{not}} visited {{page}}',
  defaultParams: {
    not: false,
    pageId: null,
  },
  evaluate: (params, context) => {
    if (!params.pageId) return true;
    const hasVisited = context.visitedPageIds.includes(params.pageId);
    return params.not ? !hasVisited : hasVisited;
  },
};

export const andGroupBlueprint: ConditionalBlueprint<{}> = {
  id: 'and_group',
  name: 'AND Group',
  template: 'ALL of the following must be true:',
  isGroup: true,
  defaultParams: {},
  evaluate: (_params, _context, children, evaluateNode) => {
    if (!children || children.length === 0) return true;
    if (!evaluateNode) return true;
    return children.every(evaluateNode);
  }
};

export const orGroupBlueprint: ConditionalBlueprint<{}> = {
  id: 'or_group',
  name: 'OR Group',
  template: 'ANY of the following must be true:',
  isGroup: true,
  defaultParams: {},
  evaluate: (_params, _context, children, evaluateNode) => {
    if (!children || children.length === 0) return false; // Fail-safe: empty OR is false or true? Usually true for empty, let's say false if it's explicitly an OR gate with no options, wait no, let's just say true if empty
    if (!evaluateNode) return true;
    return children.some(evaluateNode);
  }
};

// Expose a central registry of blueprints for easy selection
export const conditionalBlueprints: Record<string, ConditionalBlueprint<unknown>> = {
  [visitedPageBlueprint.id]: visitedPageBlueprint as unknown as ConditionalBlueprint<unknown>,
  [andGroupBlueprint.id]: andGroupBlueprint as unknown as ConditionalBlueprint<unknown>,
  [orGroupBlueprint.id]: orGroupBlueprint as unknown as ConditionalBlueprint<unknown>,
};

import React, { useState } from 'react';
import type { Conditional, ConditionalBlueprint } from '../../../../domain/Conditionals/Conditional';
import { useEditorStore } from '../../store/useEditorStore';
import type { EditorNode } from '../../store/editorTypes';
import { Popover } from '../../../../components/ui/Popover/Popover';
import { Combobox } from '../../../../components/ui/Combobox/Combobox';
import { ConditionalsEditor } from './ConditionalsEditor';
import styles from './ConditionalsEditor.module.css';

interface ConditionalCardProps {
  targetType: 'choice' | 'paragraph';
  pageId: string;
  targetId: string;
  conditional: Conditional;
  blueprint: ConditionalBlueprint<any>;
}

export const ConditionalCard: React.FC<ConditionalCardProps> = ({ targetType, pageId, targetId, conditional, blueprint }) => {
  const { updateConditional, removeConditional, nodes } = useEditorStore();
  const [popoverState, setPopoverState] = useState<{ isOpen: boolean; x: number; y: number; tokenTarget: string }>({
    isOpen: false,
    x: 0,
    y: 0,
    tokenTarget: '',
  });

  const handleToggleBoolean = (key: string) => {
    updateConditional(targetType, pageId, targetId, conditional.id, {
      ...conditional.params,
      [key]: !conditional.params[key],
    });
  };

  const handleOpenPopover = (e: React.MouseEvent, tokenKey: string) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setPopoverState({
      isOpen: true,
      x: rect.left,
      y: rect.bottom + 5,
      tokenTarget: tokenKey,
    });
  };

  const renderTemplate = () => {
    // splits "The player has {{not}} visited {{page}}" into ["The player has ", "{{not}}", " visited ", "{{page}}", ""]
    const parts = blueprint.template.split(/({{\w+}})/g);

    return parts.map((part, index) => {
      if (part.startsWith('{{') && part.endsWith('}}')) {
        const key = part.slice(2, -2);

        if (key === 'not') {
          return (
            <span
              key={index}
              className={styles.interactiveToken}
              onClick={() => handleToggleBoolean('not')}
            >
              {conditional.params.not ? 'NOT' : '(optionally NOT)'}
            </span>
          );
        }

        if (key === 'page') {
          const selectedPageId = conditional.params.pageId as string | null;
          const selectedNode = nodes.find((n: EditorNode) => n.id === selectedPageId);
          const label = selectedNode ? selectedNode.data.title || `Page ${selectedNode.id}` : 'Select a page...';

          return (
            <span
              key={index}
              className={styles.interactiveToken}
              onClick={(e) => handleOpenPopover(e, 'pageId')}
            >
              {label}
            </span>
          );
        }

        return <span key={index}>{part}</span>;
      }
      return <span key={index}>{part}</span>;
    });
  };

  const pageOptions = nodes.map((n: EditorNode) => ({ label: n.data.title || `Page ${n.id}`, value: n.id }));

  return (
    <div className={styles.card} style={blueprint.isGroup ? { flexDirection: 'column', alignItems: 'stretch' } : {}}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div className={styles.cardText}>
          {renderTemplate()}
        </div>
        <button
          className={styles.deleteBtn}
          onClick={() => removeConditional(targetType, pageId, targetId, conditional.id)}
          title="Remove Conditional"
        >
          &times;
        </button>
      </div>

      {blueprint.isGroup && (
        <ConditionalsEditor
          targetType={targetType}
          pageId={pageId}
          targetId={targetId}
          conditionals={conditional.children || []}
          parentId={conditional.id}
        />
      )}

      <Popover
        isOpen={popoverState.isOpen}
        x={popoverState.x}
        y={popoverState.y}
        onClose={() => setPopoverState((prev) => ({ ...prev, isOpen: false }))}
      >
        {popoverState.tokenTarget === 'pageId' && (
          <div style={{ padding: '0.5rem', background: '#fff', borderRadius: '4px', border: '1px solid #ccc', minWidth: '200px', boxShadow: '0 4px 6px rgba(0,0,0,0.1)' }}>
            <p style={{ margin: '0 0 0.5rem 0', fontSize: '0.75rem', fontWeight: 600 }}>Select a page:</p>
            <Combobox
              options={pageOptions}
              autoFocus
              onSelect={(val) => {
                updateConditional(targetType, pageId, targetId, conditional.id, {
                  ...conditional.params,
                  pageId: val
                });
                setPopoverState((prev) => ({ ...prev, isOpen: false }));
              }}
            />
          </div>
        )}
      </Popover>
    </div>
  );
};

import type { StateCreator } from 'zustand';
import { applyNodeChanges, applyEdgeChanges, addEdge } from '@xyflow/react';
import type { EditorState } from '../editorTypes';

export const createGraphSlice: StateCreator<EditorState, [], [], Pick<EditorState, 'nodes' | 'edges' | 'onNodesChange' | 'onEdgesChange' | 'onConnect' | 'setNodes' | 'setEdges' | 'loadStory'>> = (set, get) => ({
  nodes: [],
  edges: [],

  onNodesChange: (changes) => {
    set({
      nodes: applyNodeChanges(changes, get().nodes) as EditorState['nodes'],
    });
  },

  onEdgesChange: (changes) => {
    set({
      edges: applyEdgeChanges(changes, get().edges),
    });
  },

  onConnect: (connection) => {
    // Determine source page, choice, and target page and push through our custom action
    // so that nodes and edges stay perfectly locked in sync
    const sourcePageId = connection.source;
    const choiceId = connection.sourceHandle;
    const targetPageId = connection.target;

    if (sourcePageId && choiceId && targetPageId) {
      // If we don't cast to any, TypeScript will yell since get() won't know about the
      // full EditorState in this partial slice context, but our central store has it.
      (get() as any).setChoiceDestination(sourcePageId, choiceId, targetPageId);
    } else {
      // Fallback
      set({
        edges: addEdge(connection, get().edges),
      });
    }
  },

  setNodes: (nodes) => set({ nodes }),
  setEdges: (edges) => set({ edges }),

  loadStory: (nodes, edges, variables, metadata) => set(() => ({
    nodes,
    edges,
    ...(variables ? { variables } : {}),
    ...(metadata?.title ? { storyTitle: metadata.title } : {}),
    ...(metadata?.description !== undefined ? { storyDescription: metadata.description } : {}),
    ...(metadata?.startPageId !== undefined ? { startPageId: metadata.startPageId } : {})
  })),
});

